<?xml version="1.0" encoding="UTF-8" standalone="no"?>
<mappingRoot xmlns="http://www.ibm.com/2008/ccl/Mapping" xmlns:map="default" domainID="com.ibm.msl.mapping.xml" domainIDExtension="mb" mainMap="true" targetNamespace="default" version="8.0.5.0">
    <input path="jar:file://!com/ibm/etools/mft/map/xsds/predefined/JsonDomainMsg.xsd" var="var1"/>
    <input derivedFrom="MB:JSON_schema_in_json_file" path="/JSONSchema.json" var="var"/>
    <output path="jar:file://!com/ibm/etools/mft/map/xsds/predefined/BlobMessage.xsd"/>
    <namespaces>
        <namespace kind="supplement" prefix="in" uri="http://www.ibm.com/iib/msl/json"/>
    </namespaces>
    <generation engine="xquery"/>
    <mappingDeclaration name="JSONtoBLOB_Mapping">
        <input namespace="http://www.ibm.com/iib/msl/json" path="$var1/mb:msg(JSON,assembly,JSON,Properties)" var="ComIbmMessageAssembly_JSON">
            <cast derivedFrom="MB:JSON_TYPE" path="$ComIbmMessageAssembly_JSON/JSON/Data/type('anyType')" qualifier="{http://www.ibm.com/iib/msl/json}JSONArray_JSONSchema_JsonType" ref="var"/>
        </input>
        <output path="mb:msg(BLOB,assembly,BLOB,Properties)" var="ComIbmMessageAssembly_BLOB"/>
        <move>
            <input path="$ComIbmMessageAssembly_JSON/Properties"/>
            <output path="$ComIbmMessageAssembly_BLOB/Properties"/>
        </move>
        <expression>
            <input path="$ComIbmMessageAssembly_JSON/JSON/spath('Data',2)/Item[1]" var="Item1"/>
            <input path="$ComIbmMessageAssembly_JSON/JSON/spath('Data',2)/Item[2]" var="Item2"/>
            <input path="$ComIbmMessageAssembly_JSON/JSON/spath('Data',2)/Item[3]" var="Item3"/>
            <input path="$ComIbmMessageAssembly_JSON/JSON/spath('Data',2)/Item[4]" var="Item4"/>
            <output path="$ComIbmMessageAssembly_BLOB/BLOB/text()"/>
            <code lang="xpath">iib:hexBinaryValue(fn:concat(&#13;
'[{',&#13;
'"LastName":"',$Item1/LastName,'"',&#13;
'"FirstName":"',$Item1/FirstName,'"',&#13;
'"Address":"',$Item1/Address,'"',&#13;
'"DateOfBirth":"',$Item1/DateOfBirth,'"',&#13;
'},',&#13;
'{',&#13;
'"LastName":"',$Item2/LastName,'"',&#13;
'"FirstName":"',$Item2/FirstName,'"',&#13;
'"Address":"',$Item2/Address,'"',&#13;
'"DateOfBirth":"',$Item2/DateOfBirth,'"',&#13;
'},',&#13;
'{',&#13;
'"LastName":"',$Item3/LastName,'"',&#13;
'"FirstName":"',$Item3/FirstName,'"',&#13;
'"Address":"',$Item3/Address,'"',&#13;
'"DateOfBirth":"',$Item3/DateOfBirth,'"',&#13;
'},',&#13;
'{',&#13;
'"LastName":"',$Item4/LastName,'"',&#13;
'"FirstName":"',$Item4/FirstName,'"',&#13;
'"Address":"',$Item4/Address,'"',&#13;
'"DateOfBirth":"',$Item4/DateOfBirth,'"',&#13;
'}]'&#13;
))</code>
        </expression>
    </mappingDeclaration>
</mappingRoot>
